namespace PZ3D {
 sealed class SafehouseTransferBounds {public int minX,minY,maxX,maxY;}
 sealed class SafehouseTransferOrder {public string id;public int sourceIndex,targetIndex;}
 sealed class SafehouseTransferPreview {
  public string previewStamp="",sourceId,targetId;public bool canTransfer,itemCountKnown=true;public SafehouseTransferBounds requestedBounds,actualBounds;public int marginChunks,chunkCount,overwrittenChunks,addedChunks;public long missingChunks,bytes,itemCount,itemsTransferred,itemsRemoved;
  public string[] sourceMods=new string[0],targetMods=new string[0],sourceOnlyMods=new string[0],targetOnlyMods=new string[0],missingTypes=new string[0],droppedTypes=new string[0],warnings=new string[0],errors=new string[0];public SafehouseTransferOrder[] orderChanges=new SafehouseTransferOrder[0];
 }
 sealed class SafehouseTransferResult {public string status="completed",message,sourceId,targetId,recoveryId;public bool itemCountKnown=true;public int chunkCount;public long itemCount,itemsTransferred,itemsRemoved;public string[] missingTypes,droppedTypes;}
 // Receipts live only in the selected controller instance. Applying one requires
 // a fresh exact fingerprint and never accepts filesystem paths from the WebView.
 sealed class SafehouseTransfer:IDisposable {
  sealed class Input {internal string scope,path,identity,hash;internal bool exists;internal long bytes;}
  sealed class Chunk {internal int x,y;internal string relative;}
  sealed class Plan {internal SafehouseTransferPreview view;internal string fingerprint,identity,sourceIdentity,targetIdentity;internal List<Input> inputs=new List<Input>();internal List<Chunk> chunks=new List<Chunk>();internal List<Chunk> caches=new List<Chunk>();internal SafehouseTransferPlan dictionary;internal DateTime created;}
  readonly Engine e;readonly string game,user,data;readonly object gate=new object();readonly Dictionary<string,Plan> previews=new Dictionary<string,Plan>(StringComparer.Ordinal);readonly CancellationTokenSource lifetime=new CancellationTokenSource();bool disposed;
  internal SafehouseTransfer(Engine engine){e=engine;game=Path.GetFullPath(e.Game);user=Path.GetFullPath(e.User);data=Path.GetFullPath(e.Data);}
  public void Dispose(){lock(gate){if(disposed)return;disposed=true;previews.Clear();lifetime.Cancel();}}
  void Owner(){lock(gate)if(disposed)throw new ObjectDisposedException("SafehouseTransfer");if(!string.Equals(game,Path.GetFullPath(e.Game),StringComparison.OrdinalIgnoreCase)||!string.Equals(user,Path.GetFullPath(e.User),StringComparison.OrdinalIgnoreCase)||!string.Equals(data,Path.GetFullPath(e.Data),StringComparison.OrdinalIgnoreCase))throw new IOException("所选版本或用户目录已变化，请重新预览。");}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=int.MaxValue};}
  static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static void Safe(string path){LauncherMaintenance.NoReparse(path);}
  static int Floor8(int tile){return tile>=0?tile/8:(int)(-((-(long)tile+7)/8));}
  static string Number(int value){return value.ToString(CultureInfo.InvariantCulture);}
  static string MapPath(int x,int y){return "map/"+Number(x)+"/"+Number(y)+".bin";}
  static string CachePath(int x,int y){return "isoregiondata/datachunk_"+Number(x)+"_"+Number(y)+".bin";}
  static string At(string root,string relative){string path=Path.GetFullPath(Path.Combine(root,relative.Replace('/',Path.DirectorySeparatorChar)));if(!path.StartsWith(Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("迁移文件路径越界。");Safe(path);return path;}
  static SafehouseTransferBounds Bounds(int x1,int y1,int x2,int y2){return new SafehouseTransferBounds{minX=Math.Min(x1,x2),minY=Math.Min(y1,y2),maxX=Math.Max(x1,x2),maxY=Math.Max(y1,y2)};}
  public SafehouseTransferPreview Preview(string sourceId,string targetId,int minX,int minY,int maxX,int maxY,int marginChunks,CancellationToken cancellation){
   Owner();using(var linked=CancellationTokenSource.CreateLinkedTokenSource(cancellation,lifetime.Token)){var view=new SafehouseTransferPreview{sourceId=sourceId,targetId=targetId,requestedBounds=Bounds(minX,minY,maxX,maxY),marginChunks=marginChunks};try{if(marginChunks!=0&&marginChunks!=1)throw new IOException("区域外扩请选择 0 或 1 个区块。");Plan plan=SaveBackups.StoppedWorldPair(e,sourceId,targetId,linked.Token,(captured,source,target)=>Build(sourceId,targetId,view.requestedBounds,marginChunks,source,target,linked.Token));view=plan.view;Owner();if(view.canTransfer){string receipt="housePreview:"+Guid.NewGuid().ToString("N");lock(gate){if(disposed)throw new ObjectDisposedException("SafehouseTransfer");foreach(string key in previews.Where(pair=>DateTime.UtcNow-pair.Value.created>TimeSpan.FromMinutes(15)).Select(pair=>pair.Key).ToArray())previews.Remove(key);if(previews.Count>=16)previews.Clear();previews.Add(receipt,plan);}view.previewStamp=receipt;}}catch(OperationCanceledException){throw;}catch(Exception error){view.canTransfer=false;view.errors=new[]{error.Message};}return view;}
  }
  public SafehouseTransferResult Apply(string previewStamp,bool confirmed,CancellationToken cancellation){
   Owner();if(!confirmed)throw new IOException("迁移需要确认当前预览中的覆盖范围和物品处理结果。");Plan issued;lock(gate){if(!previews.TryGetValue(previewStamp??"",out issued)||DateTime.UtcNow-issued.created>TimeSpan.FromMinutes(15))throw new IOException("迁移预览未由当前窗口签发或已失效，请重新预览。");previews.Remove(previewStamp);}using(var linked=CancellationTokenSource.CreateLinkedTokenSource(cancellation,lifetime.Token)){CancellationToken token=linked.Token;return SaveBackups.StoppedWorldPair(e,issued.view.sourceId,issued.view.targetId,token,(captured,source,target)=>{
    var bounds=issued.view.requestedBounds;Plan fresh=Build(issued.view.sourceId,issued.view.targetId,bounds,issued.view.marginChunks,source,target,token);if(!fresh.view.canTransfer||fresh.fingerprint!=issued.fingerprint)throw new IOException("预览后的来源、目标或模组/字典文件已变化，请重新预览。");Owner();var edit=SaveBackups.EditWorld(e,fresh.view.sourceId,fresh.view.targetId,"房屋迁移前的完整存档",(sourceRoot,stage,ct)=>Patch(fresh,sourceRoot,stage,ct),(sourceRoot,targetRoot,ct)=>{Owner();Verify(fresh,sourceRoot,targetRoot,ct);},token);return new SafehouseTransferResult{sourceId=fresh.view.sourceId,targetId=fresh.view.targetId,recoveryId=edit.recoveryId,chunkCount=fresh.view.chunkCount,itemCountKnown=fresh.view.itemCountKnown,itemCount=fresh.view.itemCount,itemsTransferred=fresh.view.itemsTransferred,itemsRemoved=fresh.view.itemsRemoved,missingTypes=fresh.view.missingTypes,droppedTypes=fresh.view.droppedTypes,message=(fresh.view.itemCountKnown?"已迁移 "+fresh.view.chunkCount+" 个区块、"+fresh.view.itemsTransferred+" 件物品；跳过 "+fresh.view.itemsRemoved+" 件目标缺失物品。":"已迁移 "+fresh.view.chunkCount+" 个区块，区块已按原始内容完整迁移；物品数量未统计。")+(edit.retainedDisplaced?"迁移前完整备份和原目录均已保留。":"迁移前完整备份已保留。")};
   });}
  }
  Plan Build(string sourceId,string targetId,SafehouseTransferBounds requested,int margin,string source,string target,CancellationToken token){
   token.ThrowIfCancellationRequested();var plan=new Plan{identity=SaveBackups.ExitIdentity(e),sourceIdentity=SaveBackups.PathIdentity(source),targetIdentity=SaveBackups.PathIdentity(target),created=DateTime.UtcNow,view=new SafehouseTransferPreview{sourceId=sourceId,targetId=targetId,requestedBounds=requested,marginChunks=margin}};var view=plan.view;int left=checked(Floor8(requested.minX)-margin),top=checked(Floor8(requested.minY)-margin),right=checked(Floor8(requested.maxX)+margin),bottom=checked(Floor8(requested.maxY)+margin);view.actualBounds=new SafehouseTransferBounds{minX=checked(left*8),minY=checked(top*8),maxX=checked(right*8+7),maxY=checked(bottom*8+7)};plan.chunks=Chunks(source,left,top,right,bottom,token);view.chunkCount=plan.chunks.Count;view.missingChunks=checked(((long)right-left+1)*((long)bottom-top+1)-plan.chunks.Count);if(plan.chunks.Count==0)throw new IOException("所选区域没有已保存的 B42 地图区块。");
   Capture(plan,"source","mods.txt",source,token);Capture(plan,"target","mods.txt",target,token);Capture(plan,"global","",e.Mods,token);var sourceProfile=Json().Deserialize<Dictionary<string,object>>(Json().Serialize(SaveProfiles.Read(e,sourceId)));var targetProfile=Json().Deserialize<Dictionary<string,object>>(Json().Serialize(SaveProfiles.Read(e,targetId)));view.sourceMods=Array(sourceProfile,"enabled");view.targetMods=Array(targetProfile,"enabled");view.sourceOnlyMods=view.sourceMods.Except(view.targetMods,StringComparer.Ordinal).ToArray();view.targetOnlyMods=view.targetMods.Except(view.sourceMods,StringComparer.Ordinal).ToArray();view.orderChanges=view.sourceMods.Select((id,index)=>new SafehouseTransferOrder{id=id,sourceIndex=index,targetIndex=System.Array.IndexOf(view.targetMods,id)}).Where(row=>row.targetIndex>=0&&row.sourceIndex!=row.targetIndex).ToArray();var warnings=new List<string>();if(view.sourceOnlyMods.Length>0||view.targetOnlyMods.Length>0||view.orderChanges.Length>0)warnings.Add("两个存档的模组及顺序有差异；目标模组清单保持原样。");if(!Array(sourceProfile,"maps").SequenceEqual(Array(targetProfile,"maps")))warnings.Add("两个存档的地图清单或顺序有差异，请核对相同世界坐标。");
   var sourceDictionary=SafehouseTransferFormat.Load(At(source,"WorldDictionary.bin"));var targetDictionary=SafehouseTransferFormat.Load(At(target,"WorldDictionary.bin"));Capture(plan,"source","WorldDictionary.bin",source,token);Capture(plan,"target","WorldDictionary.bin",target,token);if(plan.inputs.Single(input=>input.scope=="source"&&input.path=="WorldDictionary.bin").hash!=sourceDictionary.Hash||plan.inputs.Single(input=>input.scope=="target"&&input.path=="WorldDictionary.bin").hash!=targetDictionary.Hash)throw new IOException("字典在读取期间变化，请重试。");plan.dictionary=SafehouseTransferFormat.Plan(sourceDictionary,targetDictionary);if(!plan.dictionary.Supported)throw new IOException(plan.dictionary.UnsupportedReason);
   var errors=new List<string>();var dropped=new HashSet<string>(StringComparer.Ordinal);foreach(var chunk in plan.chunks){token.ThrowIfCancellationRequested();var input=Capture(plan,"source",chunk.relative,source,token);byte[] raw=Read(At(source,chunk.relative),token);if(Hash(raw)!=input.hash)throw new IOException("来源区块在分析期间变化。");var converted=SafehouseTransferFormat.TransformChunk(raw,plan.dictionary);if(converted.Bytes==null||!string.IsNullOrEmpty(converted.UnsupportedReason)){view.itemCountKnown=false;errors.Add("区块 "+chunk.x+","+chunk.y+"："+converted.UnsupportedReason);continue;}view.bytes=checked(view.bytes+raw.LongLength);if(converted.ItemCountKnown){view.itemCount=checked(view.itemCount+converted.ItemQuantity);view.itemsTransferred=checked(view.itemsTransferred+converted.ItemsTransferred);}else view.itemCountKnown=false;view.itemsRemoved=checked(view.itemsRemoved+converted.ItemsRemoved);dropped.UnionWith(converted.DroppedTypes);var destination=Capture(plan,"target",MapPath(chunk.x,chunk.y),target,token);if(destination.exists)view.overwrittenChunks++;else view.addedChunks++;}
   if(!view.itemCountKnown){view.itemCount=-1;view.itemsTransferred=-1;if(errors.Count==0)warnings.Add("区块会按原始内容完整迁移；物品数量未统计。");}
   plan.caches=Neighbors(plan.chunks);foreach(var cache in plan.caches)Capture(plan,"target",CachePath(cache.x,cache.y),target,token);var header=Capture(plan,"target","isoregiondata/RegionHeader.bin",target,token);if(header.exists)RegionHeader(Read(At(target,header.path),token),null);if(view.itemsRemoved>0)warnings.Add("目标缺少部分物品类型；当前预览列明的物品数量将跳过，其他可识别物品继续迁移。");view.droppedTypes=dropped.OrderBy(value=>value,StringComparer.Ordinal).ToArray();view.missingTypes=plan.dictionary.MissingTypes.Intersect(dropped,StringComparer.Ordinal).ToArray();view.warnings=warnings.ToArray();view.errors=errors.ToArray();view.canTransfer=errors.Count==0;Verify(plan,source,target,token);plan.fingerprint=Hash(Encoding.UTF8.GetBytes(Json().Serialize(new{identity=plan.identity,source=plan.sourceIdentity,target=plan.targetIdentity,sourceId=sourceId,targetId=targetId,bounds=requested,margin=margin,sourceMods=view.sourceMods,targetMods=view.targetMods,inputs=plan.inputs.OrderBy(input=>input.scope,StringComparer.Ordinal).ThenBy(input=>input.path,StringComparer.Ordinal).Select(input=>new{scope=input.scope,path=input.path,exists=input.exists,identity=input.identity,hash=input.hash,bytes=input.bytes}).ToArray()})));return plan;
  }
  static string[] Array(Dictionary<string,object> values,string key){return ((System.Collections.IEnumerable)values[key]).Cast<object>().Select(Convert.ToString).ToArray();}
  static Input Capture(Plan plan,string scope,string relative,string root,CancellationToken token){var input=Inspect(scope,relative,root,token);plan.inputs.Add(input);return input;}
  static Input Inspect(string scope,string relative,string root,CancellationToken token){token.ThrowIfCancellationRequested();string path=scope=="global"?root:At(root,relative);Safe(path);if(Directory.Exists(path))throw new IOException("迁移所需文件位置是目录。");if(!File.Exists(path))return new Input{scope=scope,path=relative,exists=false,hash="missing",identity=""};using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){string identity=SaveBackups.PathIdentity(path);using(var sha=SHA256.Create()){byte[] buffer=new byte[131072];long total=0;int count;while((count=input.Read(buffer,0,buffer.Length))!=0){token.ThrowIfCancellationRequested();sha.TransformBlock(buffer,0,count,null,0);total+=count;}sha.TransformFinalBlock(new byte[0],0,0);if(total!=input.Length||SaveBackups.PathIdentity(path)!=identity)throw new IOException("迁移输入文件在读取期间变化。");return new Input{scope=scope,path=relative,exists=true,bytes=total,identity=identity,hash=BitConverter.ToString(sha.Hash).Replace("-","").ToLowerInvariant()};}}}
  static byte[] Read(string path,CancellationToken token){Safe(path);using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(input.Length>int.MaxValue)throw new IOException("单个二进制区块超过当前转换器可表示范围。");using(var output=new MemoryStream()){byte[] buffer=new byte[131072];int count;while((count=input.Read(buffer,0,buffer.Length))!=0){token.ThrowIfCancellationRequested();output.Write(buffer,0,count);}if(output.Length!=input.Length)throw new IOException("二进制文件未完整读取。");return output.ToArray();}}}
  static List<Chunk> Chunks(string root,int left,int top,int right,int bottom,CancellationToken token){string map=At(root,"map");var result=new List<Chunk>();var seen=new HashSet<string>(StringComparer.Ordinal);if(!Directory.Exists(map))return result;foreach(string directory in Directory.EnumerateDirectories(map)){token.ThrowIfCancellationRequested();int x;if(!int.TryParse(Path.GetFileName(directory),NumberStyles.AllowLeadingSign,CultureInfo.InvariantCulture,out x)||x<left||x>right)continue;Safe(directory);if(Path.GetFileName(directory)!=Number(x))throw new IOException("来源区块目录坐标名称不规范。");foreach(string file in Directory.EnumerateFiles(directory,"*.bin")){token.ThrowIfCancellationRequested();int y;if(!int.TryParse(Path.GetFileNameWithoutExtension(file),NumberStyles.AllowLeadingSign,CultureInfo.InvariantCulture,out y)||y<top||y>bottom)continue;Safe(file);if(Path.GetFileName(file)!=Number(y)+".bin"||!seen.Add(Number(x)+","+Number(y)))throw new IOException("来源区块坐标重复或名称不规范。");result.Add(new Chunk{x=x,y=y,relative=MapPath(x,y)});}}return result.OrderBy(chunk=>chunk.x).ThenBy(chunk=>chunk.y).ToList();}
  static List<Chunk> Neighbors(IEnumerable<Chunk> chunks){var seen=new HashSet<string>(StringComparer.Ordinal);var result=new List<Chunk>();foreach(var chunk in chunks)for(int dx=-1;dx<=1;dx++)for(int dy=-1;dy<=1;dy++){int x=checked(chunk.x+dx),y=checked(chunk.y+dy);if(seen.Add(Number(x)+","+Number(y)))result.Add(new Chunk{x=x,y=y});}return result;}
  void Verify(Plan plan,string source,string target,CancellationToken token){token.ThrowIfCancellationRequested();if(SaveBackups.ExitIdentity(e)!=plan.identity||SaveBackups.PathIdentity(source)!=plan.sourceIdentity||SaveBackups.PathIdentity(target)!=plan.targetIdentity)throw new IOException("来源、目标或所选版本目录身份已变化。");var bounds=plan.view.actualBounds;var chunks=Chunks(source,Floor8(bounds.minX),Floor8(bounds.minY),Floor8(bounds.maxX),Floor8(bounds.maxY),token);if(!chunks.Select(chunk=>chunk.relative).SequenceEqual(plan.chunks.Select(chunk=>chunk.relative)))throw new IOException("来源区域的区块集合已变化。");foreach(var expected in plan.inputs){string root=expected.scope=="source"?source:expected.scope=="target"?target:e.Mods;var actual=Inspect(expected.scope,expected.path,root,token);if(expected.exists!=actual.exists||expected.hash!=actual.hash||expected.identity!=actual.identity||expected.bytes!=actual.bytes)throw new IOException("预览后的来源、目标或模组/字典文件已变化。");}}
  SaveWorldChange[] Patch(Plan plan,string source,string stage,CancellationToken token){var changes=new List<SaveWorldChange>();foreach(var chunk in plan.chunks){token.ThrowIfCancellationRequested();byte[] raw=Read(At(source,chunk.relative),token);var converted=SafehouseTransferFormat.TransformChunk(raw,plan.dictionary);if(converted.Bytes==null||!string.IsNullOrEmpty(converted.UnsupportedReason))throw new IOException(converted.UnsupportedReason);string relative=MapPath(chunk.x,chunk.y);Write(stage,relative,converted.Bytes);changes.Add(new SaveWorldChange{path=relative,hash=Hash(converted.Bytes),bytes=converted.Bytes.LongLength});if(e.Progress!=null)e.Progress(-1,"迁移区块："+chunk.x+","+chunk.y);}
   foreach(var cache in plan.caches){token.ThrowIfCancellationRequested();string relative=CachePath(cache.x,cache.y),path=At(stage,relative);if(File.Exists(path)){Safe(path);File.Delete(path);changes.Add(new SaveWorldChange{path=relative,deleted=true});}}string header="isoregiondata/RegionHeader.bin",headerPath=At(stage,header);if(File.Exists(headerPath)){var hashes=new HashSet<int>(plan.caches.Select(cache=>unchecked((cache.y<<16)^cache.x)));byte[] bytes=RegionHeader(Read(headerPath,token),hashes);Write(stage,header,bytes);changes.Add(new SaveWorldChange{path=header,hash=Hash(bytes),bytes=bytes.LongLength});}return changes.ToArray();
  }
  static void Write(string stage,string relative,byte[] bytes){string path=At(stage,relative);Safe(Path.GetDirectoryName(path));Directory.CreateDirectory(Path.GetDirectoryName(path));Safe(path);using(var output=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.None)){output.Write(bytes,0,bytes.Length);output.Flush(true);}}
  static int Int(byte[] bytes,int offset){return unchecked((int)(((uint)bytes[offset]<<24)|((uint)bytes[offset+1]<<16)|((uint)bytes[offset+2]<<8)|bytes[offset+3]));}
  static void Int(Stream output,int value){output.WriteByte((byte)(value>>24));output.WriteByte((byte)(value>>16));output.WriteByte((byte)(value>>8));output.WriteByte((byte)value);}
  static byte[] RegionHeader(byte[] bytes,HashSet<int> removed){if(bytes.Length<8)throw new IOException("IsoRegion 缓存索引已截断。");int count=Int(bytes,4);if(count<0||8L+4L*count!=bytes.LongLength)throw new IOException("IsoRegion 缓存索引长度无效。");if(removed==null)return bytes;var retained=new List<int>();for(int i=0;i<count;i++){int value=Int(bytes,8+i*4);if(!removed.Contains(value))retained.Add(value);}using(var output=new MemoryStream()){Int(output,Int(bytes,0));Int(output,retained.Count);foreach(int value in retained)Int(output,value);return output.ToArray();}}
 }
